# Fast prime number sieve
def primes_up_to(n):
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False
    return [i for i in range(n + 1) if is_prime[i]]

# Compute modular transition function
def T(p):
    return p % 10

# Compute autocorrelation function
def autocorr(x, lag):
    mean = np.mean(x)
    var = np.var(x)
    acf = []
    for k in range(lag):
        acf.append(np.mean((x[:-k] - mean) * (x[k:] - mean)) / var)
    return acf

