import numpy as np

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def prime_gaps(n):
    primes = []
    p = 2
    while len(primes) < n:
        if is_prime(p):
            primes.append(p)
        p += 1
    gaps = [primes[i+1] - primes[i] for i in range(len(primes)-1)]
    return gaps

def modular_autocorrelation(gaps):
    N = len(gaps)
    C = np.zeros(10)
    for k in range(1, 10):
        count = 0
        for g in gaps:
            if g % 10 == k:
                count += 1
        C[k] = count / (N - k)
    return C

