import math

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def count_transitions(primes, mod=10):
    transition_counts = [[0 for _ in range(mod)] for _ in range(mod)]
    for i in range(len(primes)-1):
        p, q = primes[i] % mod, primes[i+1] % mod
        transition_counts[p][q] += 1
    return transition_counts

def verify_conjecture(max_prime=500000):
    primes = [p for p in range(2, max_prime+1) if is_prime(p)]
    transitions = count_transitions(primes)

    for i in [1, 3, 7, 9]:
        for j in [1, 3, 7, 9]:
            p_ij = transitions[i][j] / sum(transitions[i])
            p_ji = transitions[10-j][10-i] / sum(transitions[10-j])
            if abs(p_ij - p_ji) >= 1e-3:
                print(f"VERDICT: FALSIFIED")
                print(f"P({i} -> {j}) = {p_ij:.4f}, P({10-j} -> {10-i}) = {p_ji:.4f}, |diff| = {abs(p_ij - p_ji):.4f}")
                return

    print("VERDICT: SUPPORTED")

verify_conjecture()
